$request = [Console]::In.ReadLine()
function Say($line) { [Console]::Out.WriteLine($line); [Console]::Out.Flush() }
if ($request -match '"action":"login"') {
    Say '{"open":"https://example.com/?client=scramjet-rs&state=a%26b%25PATH%25"}'
    Start-Sleep -Seconds 2
    Say '{"credential":{"access":"try-token","refresh":"try","expires":99999999999999}}'
} elseif ($request -match '"action":"refresh"') {
    Say '{"credential":{"access":"try-token","expires":99999999999999}}'
} elseif ($request -match '"action":"models"') {
    Say '{"provider":{"baseUrl":"http://127.0.0.1:9/v1","api":"openai-responses","models":[{"id":"acme-large","name":"Acme Large"}]}}'
} else {
    Say '{"error":"unknown action"}'
}
